from pathlib import Path
import nbformat as nbf

out = Path(__file__).with_name("spatial_averaging_qc.ipynb")
load = "import pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\nimport seaborn as sns\nfrom pathlib import Path\nfrom IPython.display import display\nresult_root=Path('/mnt/newStor/paros/paros_WORK/xintong/results/native_surface_analysis')\nfiles=[result_root/'spatial_averaging_pilot/tables/metrics_summary.csv']\nfiles.extend(sorted((result_root/'spatial_averaging_five_subjects/shards').glob('D*/tables/metrics_summary.csv')))\nfiles.extend(sorted((result_root/'spatial_averaging_k64_k128/shards').glob('D*/tables/metrics_summary.csv')))\nframes=[pd.read_csv(path) for path in files if path.exists()]\nmetrics=pd.concat(frames,ignore_index=True).drop_duplicates(subset=['subject','hemisphere','region','method','k','repeat'])\nmetrics=metrics[metrics.status.eq('valid')].copy()\nmetrics['method_label']=metrics.method.map({'region':'Whole-region','spatial':'Spatial grouping','random':'Random grouping'})\nprint(f'Subjects: {metrics.subject.nunique()}; regions: {metrics.region.nunique()}')"
subject = "keys=['subject','hemisphere','region','method','k']\nsubject_metrics=metrics.groupby(keys,as_index=False).agg(mae=('mae','median'),rmse=('rmse','median'))\nbase=subject_metrics[subject_metrics.method.eq('region')&subject_metrics.k.eq(1)].rename(columns={'mae':'region_mae','rmse':'region_rmse'})[['subject','hemisphere','region','region_mae','region_rmse']]\nsubject_metrics=subject_metrics.merge(base,on=['subject','hemisphere','region'],how='left')\nsubject_metrics['mae_improvement_pct']=100*(subject_metrics.region_mae-subject_metrics.mae)/subject_metrics.region_mae\nsubject_metrics['rmse_improvement_pct']=100*(subject_metrics.region_rmse-subject_metrics.rmse)/subject_metrics.region_rmse\ndisplay(subject_metrics.head())"
summary = "summary=subject_metrics.groupby(['region','method','k'],as_index=False).agg(n_subjects=('subject','nunique'),mae_median=('mae','median'),mae_q25=('mae',lambda x:x.quantile(.25)),mae_q75=('mae',lambda x:x.quantile(.75)),rmse_median=('rmse','median'),rmse_q25=('rmse',lambda x:x.quantile(.25)),rmse_q75=('rmse',lambda x:x.quantile(.75)),improvement_median=('mae_improvement_pct','median'),improvement_q25=('mae_improvement_pct',lambda x:x.quantile(.25)),improvement_q75=('mae_improvement_pct',lambda x:x.quantile(.75)),subjects_improved=('mae_improvement_pct',lambda x:int((x>0).sum())))\nsummary['improved_subject_pct']=100*summary.subjects_improved/summary.n_subjects\ndisplay(summary.round(4))"
plot = "plot_summary=summary[summary.k.le(32)].copy()\nfig,axes=plt.subplots(1,plot_summary.region.nunique(),figsize=(4*plot_summary.region.nunique(),3.4),squeeze=False)\nfor ax,region in zip(axes.ravel(),sorted(plot_summary.region.unique())):\n    part=plot_summary[plot_summary.region.eq(region)]\n    baseline=part[part.method.eq('region')&part.k.eq(1)]\n    if len(baseline):\n        ax.axhline(baseline.mae_median.iloc[0],color='#777777',linestyle='--',linewidth=1.2,label='Baseline')\n    for method,color,label in [('spatial','#0072B2','Spatial grouping'),('random','#D55E00','Random grouping')]:\n        line=part[part.method.eq(method)].sort_values('k')\n        if len(line):\n            ax.plot(line.k,line.mae_median,marker='o',label=label,color=color)\n            ax.fill_between(line.k,line.mae_q25,line.mae_q75,color=color,alpha=.15)\n    ax.set_title(region)\n    ax.set_xlabel('K')\n    ax.set_ylabel('Subject-level median MAE')\n    ax.set_xticks([1,2,4,8,16,32])\n    ax.set_xlim(0.5,32.5)\n    ax.spines[['top','right']].set_visible(False)\naxes.ravel()[0].legend(frameon=False,fontsize=7)\nfig.tight_layout()\nplt.show()"
improve = "spatial=summary[summary.method.eq('spatial')]\nfig,ax=plt.subplots(figsize=(6.5,3.8))\nsns.lineplot(data=spatial,x='k',y='improvement_median',hue='region',marker='o',ax=ax)\nax.axhline(0,color='black',linewidth=.8)\nax.set_xlabel('K')\nax.set_ylabel('MAE improvement vs whole-region mean (%)',labelpad=8)\nax.set_xticks([2,4,8,16,32,64,128])\nax.spines[['top','right']].set_visible(False)\nfig.tight_layout(pad=1.2)\nplt.show()"
subject_plot = "spatial_subject=subject_metrics[subject_metrics.method.eq('spatial')].copy()\nsubject_curve=spatial_subject.groupby(['subject','region','k'],as_index=False).agg(mae_improvement_pct=('mae_improvement_pct','median'))\nregions=sorted(subject_curve.region.unique())\nfig,axes=plt.subplots(1,len(regions),figsize=(4*len(regions),3.4),squeeze=False)\nfor ax,region in zip(axes.ravel(),regions):\n    part=subject_curve[subject_curve.region.eq(region)]\n    for subject,group in part.groupby('subject'):\n        group=group.sort_values('k')\n        ax.plot(group.k,group.mae_improvement_pct,color='#0072B2',alpha=.25,linewidth=.8)\n    median=part.groupby('k',as_index=False).mae_improvement_pct.median()\n    ax.plot(median.k,median.mae_improvement_pct,color='#0072B2',marker='o',linewidth=1.8,label='Across-subject median')\n    ax.axhline(0,color='black',linewidth=.8)\n    ax.set_title(region)\n    ax.set_xlabel('K')\n    ax.set_ylabel('MAE improvement (%)')\n    ax.set_xticks([2,4,8,16,32,64,128])\n    ax.spines[['top','right']].set_visible(False)\naxes.ravel()[0].legend(frameon=False,fontsize=7)\nfig.suptitle('Light lines: subject-level median across hemispheres; thick line: across-subject median',fontsize=9)\nfig.tight_layout(rect=[0,0,1,.94])\nplt.show()"
subject_mae_plot = "mae_subject=subject_metrics.copy()\nmae_subject=mae_subject[mae_subject.method.isin(['region','spatial'])].copy()\nmae_subject=mae_subject.groupby(['subject','region','method','k'],as_index=False).agg(mae=('mae','median'))\nmae_subject=mae_subject[mae_subject.k.le(128)]\nregions=sorted(mae_subject.region.unique())\nfig,axes=plt.subplots(1,len(regions),figsize=(4*len(regions),3.4),squeeze=False)\nmethod_styles={'region':('#777777','--','Baseline'),'spatial':('#0072B2','-','Spatial grouping')}\nfor ax,region in zip(axes.ravel(),regions):\n    part=mae_subject[mae_subject.region.eq(region)]\n    for method,(color,linestyle,label) in method_styles.items():\n        method_part=part[part.method.eq(method)]\n        for subject,group in method_part.groupby('subject'):\n            group=group.sort_values('k')\n            ax.plot(group.k,group.mae,color=color,linestyle=linestyle,alpha=.22,linewidth=.7)\n        median=method_part.groupby('k',as_index=False).mae.median()\n        ax.plot(median.k,median.mae,color=color,linestyle=linestyle,marker='o',linewidth=1.6,label=label)\n    ax.set_title(region)\n    ax.set_xlabel('K')\n    ax.set_ylabel('Subject-level median MAE')\n    ax.set_xticks([1,2,4,8,16,32,64,128])\n    ax.set_xlim(.5,128.5)\n    ax.spines[['top','right']].set_visible(False)\naxes.ravel()[0].legend(frameon=False,fontsize=7)\nfig.suptitle('Thin lines: subject-level median across hemispheres; thick lines: across-subject median',fontsize=9)\nfig.tight_layout(rect=[0,0,1,.94])\nplt.show()"
cells=[nbf.v4.new_markdown_cell('# Fixed 50% depth spatial averaging QC\n\nStatistics are computed within subject first, then summarized across subjects. The notebook combines the original pilot with the five additional subjects.'),nbf.v4.new_code_cell(load),nbf.v4.new_markdown_cell('## Subject-level metrics'),nbf.v4.new_code_cell(subject),nbf.v4.new_markdown_cell('## Across-subject median and interquartile range'),nbf.v4.new_code_cell(summary),nbf.v4.new_markdown_cell('## Region-specific MAE curves through K=32'),nbf.v4.new_code_cell(plot),nbf.v4.new_markdown_cell('## Spatial grouping improvement'),nbf.v4.new_code_cell(improve),nbf.v4.new_markdown_cell('## Subject-level improvement curves'),nbf.v4.new_code_cell(subject_plot),nbf.v4.new_markdown_cell('## Subject-level MAE curves through K=128'),nbf.v4.new_code_cell(subject_mae_plot)]
nb=nbf.v4.new_notebook(cells=cells); nb['metadata']['kernelspec']={'display_name':'Python 3','language':'python','name':'python3'}; out.write_text(nbf.writes(nb),encoding='utf-8'); print(out)
